def compute(vars):
    try:
        operating_lease_commitments = vars["v1"]
        total_payment_commitments = vars["v2"]

        if total_payment_commitments == 0:
            return None

        ratio = operating_lease_commitments / total_payment_commitments
        value = ratio * 100

        return {
            "value": value,
            "trace": {
                "operating_lease_commitments": operating_lease_commitments,
                "total_payment_commitments": total_payment_commitments,
                "ratio": ratio,
                "output_meta": {
                    "currency": None,
                    "scale": "ones",
                    "unit": "percentage"
                }
            }
        }
    except ZeroDivisionError:
        return None
